const c = {...$input.first().json};
const required = ['channelName','elevenLabsVoiceId','elevenLabsModel','openaiModel'];
for (const key of required) {
  if (typeof c[key] !== 'string' || !c[key].trim() || /YOUR_|PLACEHOLDER/.test(c[key]))
    throw new Error('Setup required: fill ' + key + ' in Video Settings.');
  c[key] = c[key].trim();
}
if (!/^[A-Za-z0-9_-]{10,100}$/.test(c.elevenLabsVoiceId)) throw new Error('Use an ElevenLabs voice ID, not a URL.');
if (!/^[a-z0-9._-]{1,100}$/i.test(c.openaiModel) || !/^[a-z0-9._-]{1,100}$/i.test(c.elevenLabsModel)) throw new Error('Invalid model ID.');
c.prompt = String(c.prompt ?? '').trim();
if (c.prompt.length < 10 || c.prompt.length > 4000) throw new Error('Video brief must contain 10 to 4000 characters.');
if (!/^\d{1,3}$/.test(String(c.categoryId)) || !/^[A-Z]{2}$/.test(c.regionCode)) throw new Error('Set a valid YouTube category ID and two-letter region code.');
if (!Number.isInteger(c.maxPolls) || c.maxPolls < 1 || c.maxPolls > 40 || !Number.isInteger(c.pollSeconds) || c.pollSeconds < 10 || c.pollSeconds > 30) throw new Error('Polling must use 1-40 checks with a 10-30 second interval.');
if (!Number.isInteger(c.maxAudioBytes) || c.maxAudioBytes < 1024 || c.maxAudioBytes > 3145728) throw new Error('Audio size limit must be between 1 KiB and 3 MiB.');
if (!Number.isFinite(c.minVideoSeconds) || !Number.isFinite(c.maxVideoSeconds) || c.minVideoSeconds < 55 || c.maxVideoSeconds > 120 || c.minVideoSeconds > c.maxVideoSeconds) throw new Error('Footage duration must remain within 55-120 seconds.');
return [{json:c, pairedItem:{item:0}}];

let p = $json.output ?? $json.text ?? $json;
if (typeof p === 'string') {
  try { p = JSON.parse(p.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')); }
  catch { throw new Error('The script model did not return valid JSON. No audio or render was requested.'); }
}
if (!p || typeof p !== 'object' || Array.isArray(p)) throw new Error('The script model returned an invalid object.');
for (const key of ['title','script','keyword']) if (typeof p[key] !== 'string') throw new Error('Missing script field: '+key);
const title=p.title.trim(), script=p.script.trim(), keyword=p.keyword.trim();
const words=script.split(/\s+/).filter(Boolean).length;
if (!title || title.length>60 || words<70 || words>130 || !keyword || keyword.length>80 || keyword.split(/\s+/).length>6) throw new Error('Generated script must contain 70-130 words and satisfy the documented title and keyword limits. Revise the brief and try again.');
return [{json:{title,script,keyword},pairedItem:{item:0}}];

const cfg=$('Validate Brief and Settings').first().json;
const source=Array.isArray($json.videos)?$json.videos:[];
const candidates=[];
for(const v of source) {
  if(!Number.isFinite(v.duration)||v.duration<cfg.minVideoSeconds||v.duration>cfg.maxVideoSeconds)continue;
  for(const f of Array.isArray(v.video_files)?v.video_files:[]) {
    const m=typeof f.link==='string'?/^https:\/\/([^\/?#]+)(\/[^#]*)?$/.exec(f.link):null;
    if(!m||!['videos.pexels.com','player.vimeo.com'].includes(m[1].toLowerCase())||/[\\\x00-\x20]/.test(f.link))continue;
    if(f.file_type!=='video/mp4'||!Number.isFinite(f.height)||!Number.isFinite(f.width)||f.height<=f.width||f.height<720||f.height>2160)continue;
    candidates.push({video_url:f.link,footageId:String(v.id??''),duration:v.duration,height:f.height});
  }
}
candidates.sort((a,b)=>Math.abs(a.height-1920)-Math.abs(b.height-1920));
if(!candidates.length)throw new Error('Pexels returned no suitable 55-120 second portrait MP4. Try a more general visual keyword or another brief. No voice or render was requested.');
return [{json:candidates[0],pairedItem:{item:0}}];

const bytes=await this.helpers.getBinaryDataBuffer(0,'data');
const max=$('Validate Brief and Settings').first().json.maxAudioBytes;
if(!bytes.length||bytes.length>max)throw new Error('Voiceover is empty or exceeds the 3 MiB inline audio limit. Shorten the script.');
const hasId3=bytes.length>=3&&bytes.subarray(0,3).toString('ascii')==='ID3';
const hasMpegFrame=bytes.length>=2&&bytes[0]===0xff&&(bytes[1]&0xe0)===0xe0&&(bytes[1]&0x06)!==0&&(bytes[1]&0x18)!==0x08;
if(!hasId3&&!hasMpegFrame)throw new Error('Voice response has no MP3 ID3 tag or MPEG audio-frame signature. No render was requested.');
return [{json:{audio_url:'data:audio/mpeg;base64,'+bytes.toString('base64'),video_url:$('Select Suitable Footage').first().json.video_url},pairedItem:{item:0}}];

const r=$json;
if(typeof r.request_id!=='string'||!r.request_id||r.request_id.length>100)throw new Error('fal did not return a valid request ID. Check the fal dashboard before submitting again.');
const root='https://queue.fal.run/fal-ai/ffmpeg-api/requests/'+encodeURIComponent(r.request_id);
if(!/^[A-Za-z0-9_-]+$/.test(r.request_id))throw new Error('Invalid fal request ID.');
for(const [key,suffix] of [['status_url','/status'],['response_url',''],['cancel_url','/cancel']])if(r[key]!==root+suffix)throw new Error('Unexpected fal '+key+'. Credential-bearing requests are restricted to the expected queue endpoint.');
return [{json:{requestId:r.request_id,statusUrl:r.status_url,responseUrl:r.response_url,cancelUrl:r.cancel_url,attempts:0},pairedItem:{item:0}}];

const prior=$('Wait for Render').item.json;
const state={...prior,attempts:prior.attempts+1,status:String($json.status??'')};
if($json.request_id&&$json.request_id!==state.requestId)throw new Error('fal returned a different render request ID.');
if($json.error||$json.error_type)throw new Error('fal reported a rendering failure. Inspect request '+state.requestId+' in your fal dashboard.');
if(!['IN_QUEUE','IN_PROGRESS','COMPLETED'].includes(state.status))throw new Error('fal returned an unsupported render status. Inspect request '+state.requestId+'.');
state.complete=state.status==='COMPLETED';
state.timedOut=!state.complete&&state.attempts>=$('Validate Brief and Settings').first().json.maxPolls;
return [{json:state,pairedItem:{item:0}}];

const state=$('Polling Limit Reached?').item.json;
const cancellation=$input.first().json;
const accepted=Number.isInteger(cancellation.statusCode)&&cancellation.statusCode>=200&&cancellation.statusCode<300;
throw new Error('Render polling limit reached for '+state.requestId+'. '+(accepted?'The cancellation request was accepted':'Cancellation was attempted but was not confirmed')+'. An in-progress job may still finish. Check the fal dashboard before retrying.');

const v=$json.video;
const url=v&&typeof v.url==='string'?v.url:'';
const m=/^https:\/\/([^\/?#]+)(\/[^#]*)?$/.exec(url);
if(!m||!(/^(?:[a-z0-9-]+\.)?fal\.media$/i.test(m[1])||m[1]==='storage.googleapis.com')||url.length>3000||/[\\\x00-\x20]/.test(url))throw new Error('fal returned an unexpected media URL. No download or upload was attempted.');
if(v.content_type&&!String(v.content_type).startsWith('video/'))throw new Error('Render result is not a video.');
if(v.file_size!==undefined&&(!Number.isSafeInteger(v.file_size)||v.file_size<=0||v.file_size>150*1024*1024))throw new Error('Rendered video has an invalid size or exceeds the 150 MiB limit.');
return [{json:{videoUrl:url},pairedItem:{item:0}}];

const item=$input.first();
if(!item.binary?.data)throw new Error('Video download did not return the expected data binary field.');
const bytes=await this.helpers.getBinaryDataBuffer(0,'data');
if(!bytes.length||bytes.length>150*1024*1024)throw new Error('Video file is empty or exceeds 150 MiB.');
if(bytes.length<16||bytes.subarray(4,8).toString('ascii')!=='ftyp')throw new Error('Downloaded file is not an MP4 container. YouTube upload was stopped.');
const boxSize=bytes.readUInt32BE(0);
if(boxSize<16||boxSize>4096||boxSize>bytes.length||(boxSize-16)%4!==0)throw new Error('Downloaded file has an invalid MP4 file-type box. YouTube upload was stopped.');
const majorBrand=bytes.subarray(8,12).toString('ascii');
const brands=[majorBrand];
for(let i=16;i<boxSize;i+=4)brands.push(bytes.subarray(i,i+4).toString('ascii'));
const imageBrands=['avif','avis','heic','heix','hevc','hevx','mif1','msf1'];
const movieBrand=brand=>/^iso[2-9m]$/.test(brand)||['mp41','mp42','avc1','dash','M4V ','MSNV'].includes(brand);
if(imageBrands.includes(majorBrand)||!brands.some(movieBrand))throw new Error('Downloaded ISO media is not an accepted MP4 video container. YouTube upload was stopped.');
return [{json:{title:$('Validate Generated Script').first().json.title},binary:{data:{...item.binary.data,fileName:'short.mp4',fileExtension:'mp4',mimeType:'video/mp4'}},pairedItem:{item:0}}];

const videoId=$json.uploadId;
if(typeof videoId!=='string'||!/^[A-Za-z0-9_-]{11}$/.test(videoId))throw new Error('YouTube did not return a valid video ID. The upload outcome is uncertain. Check YouTube Studio before retrying.');
return [{json:{videoId,videoUrl:'https://www.youtube.com/watch?v='+videoId,title:$('Validate Generated Script').first().json.title,requestedPrivacyStatus:'private'},pairedItem:{item:0}}];
